export function getVerseForDay(dayOfYear: number): DailyVerse {
  // Wrap around if dayOfYear > 365
  const normalizedDay = ((dayOfYear - 1) % 365) + 1;
  const verse = dailyVerses.find(v => v.dayOfYear === normalizedDay);
  if (!verse) {
    // Fallback to day 1 if somehow not found
    return dailyVerses[0];
  }
  return verse;
}

export function getVerseForToday(): DailyVerse {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now.getTime() - start.getTime();
  const oneDay = 1000 * 60 * 60 * 24;
  const dayOfYear = Math.floor(diff / oneDay);
  return getVerseForDay(dayOfYear);
}
